// --- comparison helpers ------------------------------------------------------

pub fn assert_close_f64(actual: f64, expected: f64) {
    let tol = 1e-6 * expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tol,
        "float mismatch: actual={actual}, expected={expected}, tol={tol}"
    );
}

pub fn assert_close_f64_slice(actual: &[f64], expected: &[f64]) {
    assert_eq!(
        actual.len(),
        expected.len(),
        "slice length mismatch: actual={actual:?}, expected={expected:?}"
    );
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        let tol = 1e-6 * e.abs().max(1.0);
        assert!(
            (a - e).abs() <= tol,
            "float mismatch at index {i}: actual={a}, expected={e}, tol={tol}"
        );
    }
}

pub fn assert_close_i64(actual: i64, expected: i64) {
    assert_eq!(actual, expected, "int mismatch");
}

